package piglatin

import (
	"strings"
)

// Sentence translates the given sentence from English to Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = transform(word)
	}
	return strings.Join(words, " ")
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

// transform applies the Pig Latin rules to a single word.
func transform(word string) string {
	if word == "" {
		return word
	}
	// Rule 1: words starting with a vowel, "xr", or "yt" just get "ay" appended.
	if isVowel(word[0]) || (len(word) > 1 && (word[0:2] == "xr" || word[0:2] == "yt")) {
		return word + "ay"
	}
	// Find where the leading consonant cluster ends.
	i := 0
	for i < len(word) {
		c := word[i]
		if c == 'q' && i+1 < len(word) && word[i+1] == 'u' {
			// Rule 3: "qu" is part of the consonant cluster.
			i += 2
			continue
		}
		if isVowel(c) {
			break
		}
		if c == 'y' && i > 0 {
			// Rule 4: "y" after consonants is treated as a vowel.
			break
		}
		i++
	}
	// Rule 2: move the consonant cluster to the end and append "ay".
	return word[i:] + word[:i] + "ay"
}
```

Wait, there's a subtle issue with the loop: if c is a vowel, we break. If c == 'y' and i > 0, we break. Otherwise i++. But what if c == 'y' and i == 0? Then i++ → continue. Good.

What about a word that's all consonants with no vowels, like "rhythm"? i advances: r(0)→1, h→2, t→3, m→4, at i=4 'y' with i>0 → break. i=4. Good. What about a word like "rth" (all consonants, no y)? i advances until len, and the loop terminates with i = len(word). Then word[i:] = "", word[:i] = word → word + "ay". That's a reasonable fallback.

Let's also check the "xr"/"yt" check: word[0:2] requires len >= 2. Handled.

